import RNA, random, sys
from multiprocessing import Pool

target = '((......((......))......(((......((......))......((......))......)))......)).....'
n = len(target)
pairs = [(0,75),(1,74),(8,17),(9,16),(24,67),(25,66),(26,65),(33,42),(34,41),(49,58),(50,57)]
comp={'A':'U','U':'A','G':'C','C':'G'}

def init_seed(seed):
    r=random.Random(seed)
    seq=list('A'*n)
    # base complementary
    for i,j in pairs:
        c=r.choice(['GC','CG'])
        seq[i]=c[0]; seq[j]=c[1]
    # randomize unpaired
    for i in range(n):
        if seq[i]=='A' and i not in [p[0] for p in pairs]+[p[1] for p in pairs]:
            seq[i]=r.choice('ACGU')
    return ''.join(seq)

def score(seq):
    fc=RNA.fold_compound(seq)
    mfe,_=fc.mfe()
    return RNA.bp_distance(mfe,target)

def sa(seed):
    r=random.Random(seed)
    cur=list(init_seed(seed))
    # force complementary pairs
    for i,j in pairs:
        cur[i]='G'; cur[j]='C'
    curscore=score(''.join(cur))
    best=list(cur); bestscore=curscore
    T=3.0
    for it in range(4000):
        i=r.randrange(n)
        # avoid paired positions
        if any(i in p for p in pairs): continue
        old=cur[i]
        cur[i]=r.choice('ACGU')
        s=''.join(cur)
        ns=score(s)
        if ns<=curscore or r.random()<pow(2.718,(curscore-ns)/max(T,0.01)):
            curscore=ns
            if ns<bestscore:
                bestscore=ns; best=list(cur)
                if ns==0:
                    return 0,''.join(best)
        else:
            cur[i]=old
        T*=0.999
    return bestscore,''.join(best)

if __name__=='__main__':
    nproc=160
    seeds=list(range(nproc))
    with Pool(nproc) as p:
        results=p.map(sa,seeds)
    results.sort()
    print('BEST',results[0],flush=True)
    # also report top few
    for r in results[:5]:
        print(r,flush=True)

