import RNA, random
from multiprocessing import Pool

target='((......((......))......(((......((......))......((......))......)))......)).....'
n=len(target)
seed_seq='GGAAAACAGGACAAAGCCAACCACGGGAUCAAAGGACAAACCCUCACUCGGAACAACCCACCAACCCCAAGCCUCCGCAGU'

def score(seq):
    fc=RNA.fold_compound(seq);mfe,_=fc.mfe()
    return RNA.bp_distance(mfe,target)

def repair(worker):
    r=random.Random(worker*97+13)
    cur=list(seed_seq)
    curd=score(''.join(cur))
    best=list(cur);bestd=curd
    T=2.0
    for it in range(120000):
        k=r.choice([1,1,2,2,3])
        idxs=r.sample(range(n),k)
        old=[cur[i] for i in idxs]
        for i in idxs:
            cur[i]=r.choice('ACGU')
        d=score(''.join(cur))
        if d<=curd or r.random()<pow(2.718,(curd-d)/max(T,0.05)):
            curd=d
            if d<bestd:
                bestd=d;best=list(cur)
                if d==0:
                    return 0,''.join(best)
        else:
            for j,i in enumerate(idxs): cur[i]=old[j]
        T*=0.99997
        if T<0.1: T=2.0
    return bestd,''.join(best)

if __name__=='__main__':
    with Pool(100) as p:
        res=p.map(repair,list(range(100)))
    res.sort()
    print('BEST',res[0],flush=True)
    for r in res[:3]: print(r,flush=True)
